#[test]
fn text_decode_unknown_instruction_is_error() {
    let result = Writer::from_text("000 BogusInstruction\n");
    assert!(result.is_err());
    if let Err(ParseError::UnknownInstruction { name, .. }) = &result {
        assert_eq!(name, "BogusInstruction");
    } else {
        panic!("expected UnknownInstruction, got {:?}", result);
    }
}

#[test]
fn text_decode_invalid_operand_is_error() {
    let result = Writer::from_text("000 Exit code:x42\n");
    assert!(result.is_err());
}

#[test]
fn text_decode_skips_blank_lines() {
    let text = "\n\n000 Exit code:i0\n\n";
    let bytecode = Writer::from_text(text).unwrap();
    let expected = encode(&[Instruction::ExitCodeImmutable(ExitCodeImmutable {
        code: 0,
    })]);
    assert_eq!(bytecode, expected);
}

